import java.sql.*; import java.util.*;
public class BookDAO implements BookRepository {
 public boolean addBook(Book b)throws SQLException{valid(b);return write("INSERT INTO books(title,author,isbn,category_id,total_copies,available_copies) VALUES(?,?,?,?,?,?)",b,0);}
 public boolean updateBook(Book b)throws SQLException{valid(b);try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try(PreparedStatement l=c.prepareStatement("SELECT total_copies-available_copies FROM books WHERE book_id=? FOR UPDATE")){l.setInt(1,b.getBookId());try(ResultSet r=l.executeQuery()){if(!r.next())return false;int issued=r.getInt(1);if(b.getTotalCopies()<issued)throw new IllegalArgumentException("Total below issued copies.");try(PreparedStatement p=c.prepareStatement("UPDATE books SET title=?,author=?,isbn=?,category_id=?,total_copies=?,available_copies=? WHERE book_id=?")){bind(p,b);p.setInt(6,b.getTotalCopies()-issued);p.setInt(7,b.getBookId());boolean x=p.executeUpdate()==1;c.commit();return x;}}}catch(Exception e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}}
 public List<Book> getAllBooks()throws SQLException{return find("SELECT b.*,c.name category_name FROM books b JOIN categories c ON b.category_id=c.category_id ORDER BY b.book_id",null);} public Book getBookById(int id)throws SQLException{List<Book>x=find("SELECT b.*,c.name category_name FROM books b JOIN categories c ON b.category_id=c.category_id WHERE book_id=?",id);return x.isEmpty()?null:x.get(0);} public List<Book> searchBooks(String q)throws SQLException{return find("SELECT b.*,c.name category_name FROM books b JOIN categories c ON b.category_id=c.category_id WHERE title LIKE ? OR isbn LIKE ?",q);}
 public boolean deleteBook(int id)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM books WHERE book_id=?")){p.setInt(1,id);return p.executeUpdate()==1;}}
 public LibraryStatistics getStatistics()throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT (SELECT COUNT(*) FROM books),(SELECT COALESCE(SUM(total_copies),0) FROM books),(SELECT COALESCE(SUM(available_copies),0) FROM books),(SELECT COUNT(*) FROM members),(SELECT COUNT(*) FROM issues WHERE status='ISSUED'),(SELECT COUNT(*) FROM issues WHERE status='ISSUED' AND due_date<CURDATE())");ResultSet r=p.executeQuery()){r.next();return new LibraryStatistics(r.getInt(1),r.getInt(2),r.getInt(3),r.getInt(4),r.getInt(5),r.getInt(6));}}
 private boolean write(String q,Book b,int z)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){bind(p,b);p.setInt(6,b.getTotalCopies());return p.executeUpdate()==1;}} private void bind(PreparedStatement p,Book b)throws SQLException{p.setString(1,b.getTitle());p.setString(2,b.getAuthor());p.setString(3,b.getIsbn());p.setInt(4,b.getCategoryId());p.setInt(5,b.getTotalCopies());} private void valid(Book b){if(b==null||b.getTitle().isBlank()||b.getIsbn().isBlank()||b.getCategoryId()<1||b.getTotalCopies()<0)throw new IllegalArgumentException("Valid title, ISBN, category and copies required.");}
 private List<Book> find(String q,Object v)throws SQLException{List<Book>x=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(q)){if(v instanceof Integer)p.setInt(1,(Integer)v);else if(v!=null){p.setString(1,"%"+v+"%");p.setString(2,"%"+v+"%");}try(ResultSet r=p.executeQuery()){while(r.next())x.add(new Book(r.getInt("book_id"),r.getString("title"),r.getString("author"),r.getString("isbn"),r.getInt("category_id"),r.getString("category_name"),r.getInt("total_copies"),r.getInt("available_copies")));}}return x;}
}
